export const BREEZY=Object.freeze({name:'Breezy',special:'Robot Transform Blast',kind:'robotBlast',duration:2.6,range:1100,color:'#ffe047',glow:'rgba(255,209,55,.4)'});
export function createBreezySpecial(a){return {kind:BREEZY.kind,owner:a.id,facing:a.facing,originX:a.x,x:a.x,age:0,ttl:BREEZY.duration,duration:BREEZY.duration,active:true,delay:0,hitCount:0,fired:false};}
export function endBreezySpecial(g,a,s){s.active=false;s.ttl=0;if(a){a.vx=0;a.actionRemaining=0;g.setState(a,a.hp>0?'idle':'ko');}}
export function updateBreezySpecial(g,s,a,b){if(!a||!b){endBreezySpecial(g,a,s);return;}a.facing=s.facing;a.vx=0;if(s.ttl>1e-9){a.state='special';a.actionRemaining=Math.max(a.actionRemaining,s.ttl);}if(!s.fired&&s.age>=1.35){s.fired=true;const dx=(b.x-s.originX)*s.facing;if(dx>=-30&&dx<=BREEZY.range&&b.y<190&&g.hit(a,b,48,s.kind,420,.42,b.x-s.facing))s.hitCount=1;}if(s.ttl<=1e-9)endBreezySpecial(g,a,s);}
export function breezyPose(f,s){const t=f.stateTime||0,p=f.attackProgress||0;let index=0;if(f.state==='special'){const a=s?.age??t;index=a<.72?20:a<1.35?21:a<2.25?22:0;}else if(f.state==='punch')index=[10,11,12,13,10][Math.min(4,Math.floor(p*5))];else if(f.state==='kick')index=[14,15,16,17,0][Math.min(4,Math.floor(p*5))];else if(f.state==='hurt'||f.state==='ko')index=19;else if(!f.grounded||f.state==='jump'||f.state==='fall')index=18;else if(f.state==='run'||f.state==='walk')index=2+Math.floor(t*12)%8;else index=t%1.2<.8?0:1;return {key:'breezy',index};}
export function drawBreezySpecial(ctx,s,g,ground){if(s.age<1.35||s.age>2.15)return;const x=s.originX+s.facing*90,y=ground-135,len=BREEZY.range;const fade=Math.min(1,(s.age-1.35)*20,(2.15-s.age)*7);ctx.save();ctx.translate(x,y);ctx.scale(s.facing,1);ctx.globalAlpha=Math.max(0,fade);ctx.shadowColor='#22aaff';ctx.shadowBlur=22;for(const [width,color] of [[62,'#168aff'],[33,'#75dfff'],[12,'#f0fdff']]){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(len,0);ctx.stroke();}ctx.fillStyle='#eaffff';ctx.beginPath();ctx.arc(0,0,22,0,Math.PI*2);ctx.fill();ctx.restore();}
